(** The module, decoded. *)
Definition fxprintf_module : module := Eval vm_compute in
  code_module fxprintf_term.

(** The term decodes to the module. *)
Lemma fxprintf_decodes : decode_module fxprintf_term = Some fxprintf_module.
Proof. vm_compute. reflexivity. Qed.

(** The function named n of the module, or an empty one. *)
Definition fxprintf_fn (n : string) : func :=
  code_function fxprintf_module n.

(** glibc's `__fxprintf_nocancel`. *)
Definition glibc_fxprintf_nocancel : func := Eval vm_compute in fxprintf_fn "__fxprintf_nocancel".
(** The module defines `__fxprintf_nocancel` as [glibc_fxprintf_nocancel]. *)
Lemma glibc_fxprintf_nocancel_found : find_direct (TAtom "__fxprintf_nocancel") fxprintf_module = Some (Defined glibc_fxprintf_nocancel).
Proof. vm_compute. reflexivity. Qed.
